//! Cargo-driven `sndblst.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is sndblst-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6e180000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe78000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe78000000u64)),
        o => panic!("sndblst-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "sdk/lib/drivers/sound/mment4/libmment4_rust.a", "sdk/lib/drivers/sound/mmebuddy/libmmebuddy_rust.a", "engine:oldnames"],
        "x86_64" => &["body", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "sdk/lib/drivers/sound/mment4/libmment4_rust.a", "sdk/lib/drivers/sound/mmebuddy/libmmebuddy_rust.a", "engine:oldnames"],
        "aarch64" => &["body", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "sdk/lib/drivers/sound/mment4/libmment4_rust.a", "sdk/lib/drivers/sound/mmebuddy/libmmebuddy_rust.a", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("sndblst-rust")
        .spec2def("dll/win32/sndblst/sndblst.spec", "sndblst.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
